def normalize_embedded_newlines(text: object) -> str:
    s = str(text or "")
    if not s:
        return ""
    s = s.replace("\u2028", "\n").replace("\u2029", "\n")
    s = s.replace("\r\n", "\n").replace("\r", "\n")
    if "\\n" in s or "\\r" in s or "\\t" in s:
        s = s.replace("\\r\\n", "\n").replace("\\n", "\n").replace("\\r", "\n").replace("\\t", "\t")
    return s

