def _map_todo_status_token(token: str) -> str:
    raw = str(token or "").strip().lower().replace("_", " ").replace("-", " ")
    raw = re.sub(r"\s+", " ", raw)
    return {
        "pending": "pending",
        "todo": "pending",
        "open": "pending",
        "not started": "pending",
        "notstarted": "pending",
        "待处理": "pending",
        "待處理": "pending",
        "未着手": "pending",
        "未开始": "pending",
        "未開始": "pending",
        "in progress": "in_progress",
        "inprogress": "in_progress",
        "doing": "in_progress",
        "working": "in_progress",
        "active": "in_progress",
        "进行中": "in_progress",
        "進行中": "in_progress",
        "处理中": "in_progress",
        "處理中": "in_progress",
        "completed": "completed",
        "complete": "completed",
        "done": "completed",
        "finish": "completed",
        "finished": "completed",
        "success": "completed",
        "succeeded": "completed",
        "passed": "completed",
        "完成": "completed",
        "完成了": "completed",
        "已完成": "completed",
        "完了": "completed",
        "blocked": "pending",
    }.get(raw, "")

