def split_todo_status_text(text: object) -> tuple[str, str]:
    probe = normalize_embedded_newlines(text).strip()
    if not probe:
        return "", ""
    status = ""
    marker_prefix = r"(?:[-*•>]+\s*)?"
    for _ in range(4):
        before = probe
        probe = re.sub(r"^\s+", "", probe)
        matched = False
        for row_status, pattern in (
            (
                "completed",
                rf"^(?:{marker_prefix})(?:"
                rf"\[x\]\s*"
                rf")",
            ),
            (
                "in_progress",
                rf"^(?:{marker_prefix})(?:"
                rf"\[>\]\s*"
                rf")",
            ),
            (
                "pending",
                rf"^(?:{marker_prefix})(?:"
                rf"\[\s*\]\s*"
                rf")",
            ),
        ):
            m = re.match(pattern, probe, flags=re.IGNORECASE)
            if not m:
                continue
            status = row_status
            probe = probe[m.end():].strip()
            matched = True
            break
        if matched:
            continue
        m = re.match(
            rf"^(?:{marker_prefix})"
            rf"(pending|todo|open|not[_\-\s]?started|doing|working|active|"
            rf"in[_\-\s]?progress|completed|complete|done|finish(?:ed)?|"
            rf"success(?:ful)?|succeed(?:ed)?|passed|blocked|"
            rf"待处理|待處理|未着手|未开始|未開始|进行中|進行中|处理中|處理中|完成|完成了|已完成|完了)"
            rf"\s*[：:\-\]]\s*",
            probe,
            flags=re.IGNORECASE,
        )
        if m:
            mapped = _map_todo_status_token(str(m.group(1) or ""))
            if mapped:
                status = mapped
            probe = probe[m.end():].strip()
            continue
        if probe == before:
            break
    return status, probe.strip()

