def make_unified_diff(path: str, old_text: str, new_text: str, max_lines: int = 400) -> tuple[str, int, int]:
    old_lines = old_text.splitlines()
    new_lines = new_text.splitlines()
    diff = list(
        difflib.unified_diff(
            old_lines,
            new_lines,
            fromfile=f"a/{path}",
            tofile=f"b/{path}",
            lineterm="",
        )
    )
    added = sum(1 for ln in diff if ln.startswith("+") and not ln.startswith("+++"))
    deleted = sum(1 for ln in diff if ln.startswith("-") and not ln.startswith("---"))
    if max_lines and len(diff) > max_lines:
        diff = diff[:max_lines] + [f"... diff truncated, total lines={len(diff)}"]
    text = "\n".join(diff) if diff else f"@@ no textual diff for {path}"
    return text, added, deleted

# split-source: order=748 original-lines=9943-9948 hash=fc6e1578f1dfb8e0

def _skip_row(text: str) -> dict:
    msg = str(text or "").strip() or "⋮"
    if not msg.startswith("⋮"):
        msg = f"⋮ {msg}"
    return {"kind": "skip", "sign": "⋮", "old_line": None, "new_line": None, "text": msg}

# split-source: order=749 original-lines=9949-9952 hash=f5d9ac4c2c90cef7


def _row_is_hot(row: dict) -> bool:
    return str((row or {}).get("kind", "")).strip().lower() in {"add", "delete"}

# split-source: order=750 original-lines=9953-9976 hash=5862d764d6ac180a


def _hotspot_index(rows: list[dict]) -> int:
    arr = [dict(x) for x in (rows or [])]
    if not arr:
        return 0
    hot = [1 if _row_is_hot(row) else 0 for row in arr]
    if not any(hot):
        return max(0, len(arr) - 1)
    prefix = [0]
    for v in hot:
        prefix.append(prefix[-1] + v)
    n = len(arr)
    radius = max(10, min(180, n // 18))
    best_idx = 0
    best_score = -1
    for i in range(n):
        a = max(0, i - radius)
        b = min(n - 1, i + radius)
        score = prefix[b + 1] - prefix[a]
        if score > best_score or (score == best_score and i > best_idx):
            best_idx = i
            best_score = score
    return best_idx

# split-source: order=751 original-lines=9977-10026 hash=6f30990ffc308229


def _compress_rows_keep_hotspot(
    rows: list[dict],
    max_rows: int,
    *,
    prefix_omitted: int = 0,
) -> tuple[list[dict], bool]:
    arr = [dict(x) for x in (rows or [])]
    limit = max(1, int(max_rows or 1))
    omitted_prefix_base = max(0, int(prefix_omitted or 0))
    if not arr:
        if omitted_prefix_base <= 0:
            return [], False
        return [_skip_row(f"⋮ ... ({omitted_prefix_base} rows omitted)")], True
    anchor = _hotspot_index(arr)
    n = len(arr)
    slots = (1 if omitted_prefix_base > 0 else 0) + 1
    slots = min(limit - 1, max(0, slots))
    start = 0
    end = n
    for _ in range(3):
        budget = max(1, limit - slots)
        if budget >= n:
            start, end = 0, n
        else:
            start = max(0, anchor - (budget // 2))
            if start + budget > n:
                start = max(0, n - budget)
            end = min(n, start + budget)
        omitted_prefix = omitted_prefix_base + start
        omitted_suffix = max(0, n - end)
        new_slots = (1 if omitted_prefix > 0 else 0) + (1 if omitted_suffix > 0 else 0)
        new_slots = min(limit - 1, max(0, new_slots))
        if new_slots == slots:
            break
        slots = new_slots
    omitted_prefix = omitted_prefix_base + start
    omitted_suffix = max(0, n - end)
    out: list[dict] = []
    if omitted_prefix > 0:
        out.append(_skip_row(f"⋮ ... ({omitted_prefix} rows omitted)"))
    out.extend(arr[start:end])
    if omitted_suffix > 0:
        out.append(_skip_row(f"⋮ ... ({omitted_suffix} rows omitted)"))
    truncated = omitted_prefix > 0 or omitted_suffix > 0
    if len(out) > limit:
        out = out[:limit]
        truncated = True
    return out, truncated

# split-source: order=752 original-lines=10027-10161 hash=220a462e9f681355


def _focused_diff_rows_from_opcodes(
    old_lines: list[str],
    new_lines: list[str],
    opcodes: list[tuple[str, int, int, int, int]],
    *,
    max_rows: int,
    context_lines: int = CODE_PREVIEW_DIFF_CONTEXT_LINES,
    merge_gap: int = CODE_PREVIEW_DIFF_MERGE_GAP,
) -> tuple[list[dict], bool]:
    context_lines = max(0, int(context_lines or 0))
    merge_gap = max(0, int(merge_gap or 0))
    max_rows = max(8, int(max_rows or 8))
    hunks: list[dict] = []
    for tag, i1, i2, j1, j2 in opcodes:
        if tag == "equal":
            continue
        old_start = max(0, i1 - context_lines)
        old_end = min(len(old_lines), i2 + context_lines)
        new_start = max(0, j1 - context_lines)
        new_end = min(len(new_lines), j2 + context_lines)
        if hunks and old_start <= (int(hunks[-1]["old_end"]) + merge_gap) and new_start <= (int(hunks[-1]["new_end"]) + merge_gap):
            hunks[-1]["old_end"] = max(int(hunks[-1]["old_end"]), old_end)
            hunks[-1]["new_end"] = max(int(hunks[-1]["new_end"]), new_end)
            hunks[-1]["change_count"] = int(hunks[-1].get("change_count", 0)) + max(1, (i2 - i1) + (j2 - j1))
        else:
            hunks.append(
                {
                    "old_start": old_start,
                    "old_end": old_end,
                    "new_start": new_start,
                    "new_end": new_end,
                    "change_count": max(1, (i2 - i1) + (j2 - j1)),
                }
            )
    if not hunks:
        return [], False

    rows: list[dict] = []
    op_idx = 0
    prev_old_end = 0
    prev_new_end = 0

    def _append_gap(old_start: int, new_start: int):
        old_gap = max(0, int(old_start) - int(prev_old_end))
        new_gap = max(0, int(new_start) - int(prev_new_end))
        gap = max(old_gap, new_gap)
        if gap > 0:
            rows.append(_skip_row(f"⋮ ... ({gap} unchanged lines omitted)"))

    for hunk in hunks:
        h_old_start = int(hunk["old_start"])
        h_old_end = int(hunk["old_end"])
        h_new_start = int(hunk["new_start"])
        h_new_end = int(hunk["new_end"])
        _append_gap(h_old_start, h_new_start)
        while op_idx < len(opcodes):
            tag, i1, i2, j1, j2 = opcodes[op_idx]
            if i2 <= h_old_start and j2 <= h_new_start:
                op_idx += 1
                continue
            if i1 >= h_old_end and j1 >= h_new_end:
                break
            if tag == "equal":
                start_old = max(i1, h_old_start)
                end_old = min(i2, h_old_end)
                offset = start_old - i1
                for old_i in range(start_old, end_old):
                    new_j = j1 + offset + (old_i - start_old)
                    if new_j < h_new_start or new_j >= h_new_end or new_j >= len(new_lines):
                        continue
                    rows.append(
                        {
                            "kind": "context",
                            "sign": " ",
                            "old_line": old_i + 1,
                            "new_line": new_j + 1,
                            "text": new_lines[new_j],
                        }
                    )
            elif tag == "delete":
                for old_i in range(max(i1, h_old_start), min(i2, h_old_end)):
                    rows.append(
                        {
                            "kind": "delete",
                            "sign": "-",
                            "old_line": old_i + 1,
                            "new_line": None,
                            "text": old_lines[old_i],
                        }
                    )
            elif tag == "insert":
                for new_j in range(max(j1, h_new_start), min(j2, h_new_end)):
                    rows.append(
                        {
                            "kind": "add",
                            "sign": "+",
                            "old_line": None,
                            "new_line": new_j + 1,
                            "text": new_lines[new_j],
                        }
                    )
            elif tag == "replace":
                for old_i in range(max(i1, h_old_start), min(i2, h_old_end)):
                    rows.append(
                        {
                            "kind": "delete",
                            "sign": "-",
                            "old_line": old_i + 1,
                            "new_line": None,
                            "text": old_lines[old_i],
                        }
                    )
                for new_j in range(max(j1, h_new_start), min(j2, h_new_end)):
                    rows.append(
                        {
                            "kind": "add",
                            "sign": "+",
                            "old_line": None,
                            "new_line": new_j + 1,
                            "text": new_lines[new_j],
                        }
                    )
            if i2 <= h_old_end and j2 <= h_new_end:
                op_idx += 1
            else:
                break
        prev_old_end = h_old_end
        prev_new_end = h_new_end
    trailing_gap = max(len(old_lines) - prev_old_end, len(new_lines) - prev_new_end)
    if trailing_gap > 0:
        rows.append(_skip_row(f"⋮ ... ({trailing_gap} unchanged lines omitted)"))
    out, truncated = _compress_rows_keep_hotspot(rows, max_rows)
    return out, bool(truncated or len(out) < len(rows))

# split-source: order=753 original-lines=10162-10194 hash=a8b71f66e76048d1


def make_numbered_diff(old_text: str, new_text: str, max_lines: int = 320) -> list[dict]:
    old_lines = old_text.splitlines()
    new_lines = new_text.splitlines()
    max_lines = max(16, int(max_lines or 320))
    sm = difflib.SequenceMatcher(a=old_lines, b=new_lines, autojunk=False)
    rows, _ = _focused_diff_rows_from_opcodes(
        old_lines,
        new_lines,
        list(sm.get_opcodes()),
        max_rows=max_lines,
        context_lines=CODE_PREVIEW_DIFF_CONTEXT_LINES,
        merge_gap=CODE_PREVIEW_DIFF_MERGE_GAP,
    )
    if rows:
        return rows
    show = min(len(new_lines), max_lines)
    out = [
        {
            "kind": "context",
            "sign": " ",
            "old_line": i + 1,
            "new_line": i + 1,
            "old_col": 1,
            "new_col": 1,
            "text": new_lines[i],
        }
        for i in range(show)
    ]
    if len(new_lines) > show:
        out.append(_skip_row(f"⋮ ... ({len(new_lines) - show} lines omitted)"))
    return out

# split-source: order=754 original-lines=10195-10208 hash=effc08a63226e126

def render_numbered_diff_text(entries: list[dict]) -> str:
    out = []
    for row in entries:
        if row.get("kind") == "skip":
            out.append(f"    {str(row.get('text') or '⋮').strip()}")
            continue
        old_ln = row.get("old_line")
        new_ln = row.get("new_line")
        ln = old_ln if old_ln is not None else new_ln
        sign = row.get("sign", " ")
        text = row.get("text", "")
        out.append(f"{str(ln or ''):>6} {sign} {text}")
    return "\n".join(out)
